// Initialize the RV3032 with proper clkout & backup switchover settings. Leaves the i2c connection shutdown.
// Note that once we get the RTC to give us our ticks then we should never need to touch it again.
rv3032_init();


// TEST CODE GOES HERE


if (persistent_data.initalized_flag!=0x01) {
    // We are presumably still in the fixture at the factory and it just powered us up for the first time after programming.

    // The pin is probably out since we are in the jig, so
    // ground the trigger pin so we can get a clean power reading without the pull-up shorted.

    SBI( TRIGGER_PDIR , TRIGGER_B );      // Out
    CBI( TRIGGER_POUT , TRIGGER_B );      // Ground

    // Show a simple test message and sleep so it can measure our power draw.
    lcd_show_testing_only_message();
    blinkforeverandever();

    // unreachable

}


// Initialize the lookup tables we use for efficiently updating the LCD
initLCDPrecomputedWordArrays();

if ( persistent_data.commisisoned_flag != 0x01 ) {

    // This is the first time we have powered up since programming at the factory, presumably we just had our batteries installed at the factory.

    // We just had batteries inserted for the first time ever, so we need to commission ourselves and get ready

    // Set the RTC with the time when we were programmed, which should be about 1 minute ago since this is the first time we are powering up from the reset after programming finished.
    // It will have the correct wall clock time until the first battery change in about 150 years. We use the RTC time to copy into `launched_time` when the trigger pin is pulled.
    // These wall-clock time values are only used for logging and diagnostics.
    writeRV3032time(&persistent_data.programmed_time);

// --- Flash bulbs off

// Set Q1 & Q2 transistor pins to output (will be driven low by default so LEDs off)
SBI( Q1_TOP_LED_PDIR , Q1_TOP_LED_B );
SBI( Q2_BOT_LED_PDIR , Q2_BOT_LED_B );


// --- TSP7A LCD voltage regulator
SBI( TSP_IN_POUT , TSP_IN_B );          // Power up TSP
SBI( TSP_IN_PDIR , TSP_IN_B );

SBI( TSP_ENABLE_POUT , TSP_ENABLE_B );  // Enable TSP
SBI( TSP_ENABLE_PDIR , TSP_ENABLE_B );

// --- Debug pins

// Debug pins - Currently unused so set low to save power. (Thanks Claude)
SBI( DEBUGA_PDIR , DEBUGA_B );
SBI( DEBUGB_PDIR , DEBUGB_B );

// --- RV3032

